<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Coupon; use Illuminate\Http\Request; use Inertia\Inertia;
class CouponController extends Controller { public function index(){return Inertia::render('Admin/Coupons',['coupons'=>Coupon::latest()->get()]);} public function store(Request $r){$d=$r->validate(['code'=>'required|max:40','type'=>'required|in:fixed,percent','value'=>'required|numeric|min:0','min_subtotal'=>'nullable|numeric|min:0','expires_at'=>'nullable|date','is_active'=>'boolean']);$d['code']=strtoupper(trim($d['code']));Coupon::create($d);return back();} public function update(Request $r,Coupon $coupon){$d=$r->validate(['code'=>'required|max:40','type'=>'required|in:fixed,percent','value'=>'required|numeric|min:0','min_subtotal'=>'nullable|numeric|min:0','expires_at'=>'nullable|date','is_active'=>'boolean']);$d['code']=strtoupper(trim($d['code']));$coupon->update($d);return back();} public function destroy(Coupon $coupon){$coupon->update(['is_active'=>false]);return back();} }
